mapper.insert:
INSERT INTO GRID_FILTER (
      FILTER_ID
    , FILTER_NM
    , USER_ID
    , PAGE_CODE
    , FILTER_MODE_YN
    , DEFAULT_YN
) VALUES (
      #{filterId}
    , #{filterNm}
    , #{userId}
    , #{pageCode}
    , #{filterModeYn}
    , #{defaultYn}
)

INSERT INTO GRID_COLUMN (
      COLUMN_ID
    , FILTER_ID
    , VISIABLE_YN
    , FILTERING_TEXT
    , FILTERING_OPER_CODE
    , COLUMN_SEQ
    , COLUMN_TYPE_CODE
    , SORTING_INFO
) VALUES (
      #{columnId}
    , #{filterId}
    , #{visiableYn}
    , #{filteringText}
    , #{filteringOperCode}
    , #{columnSeq}
    , #{columnTypeCode}
    , #{sortingInfo}
)

mapper.select:
SELECT FILTER_ID
     , FILTER_NM
     , USER_ID
     , PAGE_CODE
     , FILTER_MODE_YN
     , DEFAULT_YN
  FROM GRID_FILTER
 WHERE USER_ID = #{userId}
   AND PAGE_CODE = #{pageCode}

    AND FILTER_NM = #{filterNm}

mapper.update:
UPDATE GRID_FILTER
   SET DEFAULT_YN = 'N'
 WHERE PAGE_CODE = #{pageCode}
   AND USER_ID = #{userId}

UPDATE GRID_FILTER
   SET DEFAULT_YN = 'Y'
 WHERE FILTER_NM = #{filterNm}
   AND PAGE_CODE = #{pageCode}
   AND USER_ID = #{userId}
